// === Tab: shader patch ===
const lightFrag = `precision highp float;
uniform vec4 uTint;
uniform sampler2D uSampler;
uniform bool isTexture;
uniform bool uEmissive;
varying highp vec2 vVertTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;
varying vec4 vColor;
void main(void) {
  if(uEmissive && !isTexture) {
    gl_FragColor = vColor;
  }
  else {
    vec4 baseColor = isTexture
      // Textures come in with premultiplied alpha. To apply tint and still have
      // premultiplied alpha output, we need to multiply the RGB channels by the
      // tint RGB, and all channels by the tint alpha.
      ? texture2D(uSampler, vVertTexCoord) * vec4(uTint.rgb/255., 1.) * (uTint.a/255.)
      // Colors come in with unmultiplied alpha, so we need to multiply the RGB
      // channels by alpha to convert it to premultiplied alpha.
      : vec4(vColor.rgb * vColor.a, vColor.a);
    gl_FragColor = vec4(baseColor.rgb * vDiffuseColor + vSpecularColor, baseColor.a);
  }
}`

const lightVert = `precision highp float;
precision highp int;

uniform mat4 uViewMatrix;

uniform bool uUseLighting;

uniform int uAmbientLightCount;
uniform vec3 uAmbientColor[5];

uniform int uDirectionalLightCount;
uniform vec3 uLightingDirection[5];
uniform vec3 uDirectionalDiffuseColors[5];
uniform vec3 uDirectionalSpecularColors[5];

uniform int uPointLightCount;
uniform vec3 uPointLightLocation[5];
uniform vec3 uPointLightDiffuseColors[5];	
uniform vec3 uPointLightSpecularColors[5];

uniform int uSpotLightCount;
uniform float uSpotLightAngle[5];
uniform float uSpotLightConc[5];
uniform vec3 uSpotLightDiffuseColors[5];
uniform vec3 uSpotLightSpecularColors[5];
uniform vec3 uSpotLightLocation[5];
uniform vec3 uSpotLightDirection[5];

uniform bool uSpecular;
uniform float uShininess;

uniform float uConstantAttenuation;
uniform float uLinearAttenuation;
uniform float uQuadraticAttenuation;

const float specularFactor = 2.0;
var float diffuseFactor = 0.73;

struct LightResult {
  float specular;
  float diffuse;
};

float _phongSpecular(
  vec3 lightDirection,
  vec3 viewDirection,
  vec3 surfaceNormal,
  float shininess) {

  vec3 R = reflect(lightDirection, surfaceNormal);
  return pow(max(0.0, dot(R, viewDirection)), shininess);
}

float _lambertDiffuse(vec3 lightDirection, vec3 surfaceNormal) {
  return max(0.0, dot(-lightDirection, surfaceNormal));
}

LightResult _light(vec3 viewDirection, vec3 normal, vec3 lightVector) {

  vec3 lightDir = normalize(lightVector);

  //compute our diffuse & specular terms
  LightResult lr;
  if (uSpecular)
    lr.specular = _phongSpecular(lightDir, viewDirection, normal, uShininess);
  lr.diffuse = _lambertDiffuse(lightDir, normal);
  return lr;
}

void totalLight(
  vec3 modelPosition,
  vec3 normal,
  out vec3 totalDiffuse,
  out vec3 totalSpecular
) {

  totalSpecular = vec3(0.0);

  if (!uUseLighting) {
    totalDiffuse = vec3(1.0);
    return;
  }

  totalDiffuse = vec3(0.0);

  vec3 viewDirection = normalize(-modelPosition);

  for (int j = 0; j < 5; j++) {
    if (j < uDirectionalLightCount) {
      vec3 lightVector = (uViewMatrix * vec4(uLightingDirection[j], 0.0)).xyz;
      vec3 lightColor = uDirectionalDiffuseColors[j];
      vec3 specularColor = uDirectionalSpecularColors[j];
      LightResult result = _light(viewDirection, normal, lightVector);
      totalDiffuse += result.diffuse * lightColor;
      totalSpecular += result.specular * lightColor * specularColor;
    }

    if (j < uPointLightCount) {
      vec3 lightPosition = (uViewMatrix * vec4(uPointLightLocation[j], 1.0)).xyz;
      vec3 lightVector = modelPosition - lightPosition;

      //calculate attenuation
      float lightDistance = length(lightVector);
      float lightFalloff = 1.0 / (uConstantAttenuation + lightDistance * uLinearAttenuation + (lightDistance * lightDistance) * uQuadraticAttenuation);
      vec3 lightColor = lightFalloff * uPointLightDiffuseColors[j];
      vec3 specularColor = lightFalloff * uPointLightSpecularColors[j];

      LightResult result = _light(viewDirection, normal, lightVector);
      totalDiffuse += result.diffuse * lightColor;
      totalSpecular += result.specular * lightColor * specularColor;
    }

    if(j < uSpotLightCount) {
      vec3 lightPosition = (uViewMatrix * vec4(uSpotLightLocation[j], 1.0)).xyz;
      vec3 lightVector = modelPosition - lightPosition;

      float lightDistance = length(lightVector);
      float lightFalloff = 1.0 / (uConstantAttenuation + lightDistance * uLinearAttenuation + (lightDistance * lightDistance) * uQuadraticAttenuation);

      vec3 lightDirection = (uViewMatrix * vec4(uSpotLightDirection[j], 0.0)).xyz;
      float spotDot = dot(normalize(lightVector), normalize(lightDirection));
      float spotFalloff;
      if(spotDot < uSpotLightAngle[j]) {
        spotFalloff = 0.0;
      }
      else {
        spotFalloff = pow(spotDot, uSpotLightConc[j]);
      }
      lightFalloff *= spotFalloff;

      vec3 lightColor = uSpotLightDiffuseColors[j];
      vec3 specularColor = uSpotLightSpecularColors[j];

      LightResult result = _light(viewDirection, normal, lightVector);

      totalDiffuse += result.diffuse * lightColor * lightFalloff;
      totalSpecular += result.specular * lightColor * specularColor * lightFalloff;
    }
  }

  totalDiffuse *= diffuseFactor;
  totalSpecular *= specularFactor;
}

attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;
attribute vec4 aVertexColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform bool uUseVertexColor;
uniform vec4 uMaterialColor;

varying highp vec2 vVertTexCoord;
varying vec3 vDiffuseColor;
varying vec3 vSpecularColor;
varying vec4 vColor;

void main(void) {

  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;

  vec3 vertexNormal = normalize(uNormalMatrix * aNormal);
  vVertTexCoord = aTexCoord;

  totalLight(viewModelPosition.xyz, vertexNormal, vDiffuseColor, vSpecularColor);

  for (int i = 0; i < 8; i++) {
    if (i < uAmbientLightCount) {
      vDiffuseColor += uAmbientColor[i];
    }
  }

  vColor = (uUseVertexColor ? aVertexColor : uMaterialColor);
}`

const oldGetLightShader = p5.RendererGL.prototype._getLightShader
p5.RendererGL.prototype._getLightShader = function() {
  if (!this._defaultLightShader) {
    this._defaultLightShader = new p5.Shader(
			this,
			lightVert,
			lightFrag
		);
  }

  return this._defaultLightShader;
};

// === Tab: mySketch ===
let f1, f2
let img1, img2
let r
let nodeColor
let hoveredNodeColor
let secondaryNodeColor
let origMouse
let saveField
let loadField
let loadLabel
let tex1, tex2
let texGraphic
let displayMode

const nodeR = 7
const nodesPerSide = 10
function makeInitialNodes() {
	const nodes = []
	for (let x = 0; x < nodesPerSide; x++) {
		const u = x / (nodesPerSide - 1)
		for (let y = 0; y < nodesPerSide; y++) {
			const v = y / (nodesPerSide - 1)
			nodes.push({
				x: u,
				y: v,
				u,
				v,
				proximity: 0,
			})
		}
	}
	return nodes
}
let nodes1 = makeInitialNodes()
let nodes2 = makeInitialNodes()
let committedNodes1 = nodes1.map((n) => ({ ...n }))
let committedNodes2 = nodes2.map((n) => ({ ...n }))
let dragging = false
let primaryIndex = 0
let fbo, fbo2

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	setAttributes({ premultipliedAlpha: true, antialias: true })
	texGraphic = createGraphics(1000, 1000)
	texGraphic.translate(texGraphic.width/2, texGraphic.height/2)
	texGraphic.imageMode(CENTER)

	nodeColor = color('blue')
	hoveredNodeColor = color('lime')
	secondaryNodeColor = color('red')

	fbo = createFramebuffer()
	fbo2 = createFramebuffer()

	drawingContext.pixelStorei(drawingContext.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true)
	drawingContext.disable(drawingContext.DEPTH_TEST)

	displayMode = createSelect()
	displayMode.option('Animate back-and-forth')
	displayMode.option('Animate continuous')
	displayMode.option('Steps')
	displayMode.selected('Animated')
	displayMode.position(width * 0.5, height * 0.15)

	f1 = createFileInput(handleFile1)
	f2 = createFileInput(handleFile2)
	f1.position(width * 0.333, height * 0.1)
	f2.position(width * 0.667, height * 0.1)

	r = createSlider(1, 100, 50)
	r.position(width * 0.5, height * 0.1)

	saveField = createButton('Save')
	saveField.mousePressed(() => saveJSON([nodes1, nodes2], 'nodes.json'))
	saveField.position(width * 0.4, height * 0.9)

	loadField = createFileInput(handleLoadNodes)
	loadField.position(width * 0.6, height * 0.9)
	loadLabel = createP('Load:')
	loadLabel.position(width * 0.55, height * 0.9)

	origMouse = createVector()
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
	displayMode.position(width * 0.5, height * 0.15)
	f1.position(width * 0.333, height * 0.1)
	f2.position(width * 0.667, height * 0.1)
	r.position(width * 0.5, height * 0.1)
	saveField.position(width * 0.4, height * 0.9)
	loadField.position(width * 0.6, height * 0.9)
	loadLabel.position(width * 0.55, height * 0.9)
}

function mousePressed() {
	dragging = true
	committedNodes1 = nodes1.map((n) => ({ ...n }))
	committedNodes2 = nodes2.map((n) => ({ ...n }))
	origMouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
}

function mouseReleased() {
	dragging = false
	committedNodes1 = nodes1.map((n) => ({ ...n }))
	committedNodes2 = nodes2.map((n) => ({ ...n }))
}

function handleFile1(file) {
	if (img1) {
		img1.remove()
		img1 = undefined
		tex1 = undefined
	}
	if (file.type === 'image') {
    img1 = createImg(file.data, '', 'anonymous', () => {
			texGraphic.clear()
			texGraphic.push()
			texGraphic.scale(min(texGraphic.width/img1.width, texGraphic.height/img1.height))
			texGraphic.image(img1, 0, 0)
			texGraphic.pop()
			tex1 = texGraphic.get()
		})
    img1.hide()
	}
}

function handleFile2(file) {
	if (img2) {
		img2.remove()
		img2 = undefined
		tex2 = undefined
	}
	if (file.type === 'image') {
    img2 = createImg(file.data, '', 'anonymous', () => {
			texGraphic.clear()
			texGraphic.push()
			texGraphic.scale(min(texGraphic.width/img2.width, texGraphic.height/img2.height))
			texGraphic.image(img2, 0, 0)
			texGraphic.pop()
			tex2 = texGraphic.get()
		})
    img2.hide()
	}
}

function handleLoadNodes(file) {
	[nodes1, nodes2] = file.data
}

const sideLength = 400
const spacing = 100
const editorW = 3 * (sideLength + spacing)
const editorH = sideLength + 2 * spacing
function draw() {
	background(255)
	if (!dragging) {
		primaryIndex = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width/2 ? 0 : 1
	}
	// clear()
	const editorScale = min(width/editorW, height/editorH)
	push()
	scale(editorScale)

	if (dragging) {
		const mouseDiff = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))).sub(origMouse).div(editorScale * sideLength)
		var nodes = primaryIndex === 0 ? nodes1 : nodes2
		const committedNodes = primaryIndex === 0 ? committedNodes1 : committedNodes2
		nodes.forEach((node, i) => {
			node.x = lerp(committedNodes[i].x + mouseDiff.x, committedNodes[i].x, node.proximity)
			node.y = lerp(committedNodes[i].y + mouseDiff.y, committedNodes[i].y, node.proximity)
		})
	}

	fbo2.draw(() => {
		clear()
		if (displayMode.value() === 'Animate back-and-forth') {
			drawMorph(map(sin(millis() * 0.002), -1, 1, 0, 1))
		} else if (displayMode.value() === 'Animate continuous') {
			drawMorph(millis() * 0.001 % 1)
		} else {
			const numSteps = 5
			for (let step = 0; step < numSteps; step++) {
				const off = map(step, 0, numSteps-1, -100, 100)
				push()
				translate(off, off)
				scale(0.5)
				drawMorph(step / (numSteps - 1))
				pop()
			}
		}
	})
	push()
	noStroke()
	texture(fbo2.color)
	plane(width, -height)
	pop()

	const keyframes = [
		{
			x: -(sideLength + spacing),
			img: img1,
			nodes: nodes1,
			id: 0,
			localMouse: createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))).sub(width/2, height/2).div(editorScale).sub(-(sideLength + spacing), 0)
		},
		{
			x: (sideLength + spacing),
			img: img2,
			nodes: nodes2,
			id: 1,
			localMouse: createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))).sub(width/2, height/2).div(editorScale).sub((sideLength + spacing), 0)
		}
	]
	if (!dragging) {
		for (const frame of keyframes) {
			for (let row = 0; row < nodesPerSide; row++) {
				for (let col = 0; col < nodesPerSide; col++) {
					const node = frame.nodes[row * nodesPerSide + col]
					const proximity = nodeProximity(
						frame.localMouse,
						node
					)
					node.proximity = proximity
				}
			}
		}
	}
	for (const frame of keyframes) {
		const other = keyframes[1 - frame.id]
		push()
		translate(frame.x, 0)
		if (frame.img) {
			push()
			scale(min(sideLength/frame.img.width, sideLength/frame.img.height))
			imageMode(CENTER)
			image(frame.img, 0, 0)
			pop()
		}

		noFill()
		stroke(0)
		for (let row = 0; row < nodesPerSide - 1; row++) {
			beginShape(QUAD_STRIP)
			for (let col = 0; col < nodesPerSide; col++) {
				for (let off = 0; off < 2; off++) {
					var node = frame.nodes[(row + off) * nodesPerSide + col]
					vertex(
						map(node.x, 0, 1, -sideLength/2, sideLength/2),
						map(node.y, 0, 1, -sideLength/2, sideLength/2)
					)
				}
			}
			endShape()
		}

		noStroke()
		for (let row = 0; row < nodesPerSide; row++) {
			for (let col = 0; col < nodesPerSide; col++) {
				var node = frame.nodes[row * nodesPerSide + col]
				const otherNode = other.nodes[row * nodesPerSide + col]
				var proximity = (primaryIndex === frame.id ? node : otherNode).proximity
				fill(lerpColor(primaryIndex === frame.id ? hoveredNodeColor : secondaryNodeColor, nodeColor, proximity))
				circle(
					map(node.x, 0, 1, -sideLength/2, sideLength/2),
					map(node.y, 0, 1, -sideLength/2, sideLength/2),
					nodeR
				)
			}
		}
		pop()
	}
	pop()

	push()
	noFill()
	circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2, r.value() * editorScale)
	pop()
}

function drawMorph(t) {
	if (tex1 && tex2) {
		push()
		textureMode(NORMAL)
		const data = [{ img: tex1, id: 0, nodes: nodes1 }, { img: tex2, id: 1, nodes: nodes2 }]
		for (const frame of data) {
			let alpha = t
			if (frame.id === 0) alpha = 1 - alpha
			fbo.draw(() => {
				push()
				clear()
				texture(frame.img)
				noStroke()
				for (let row = 0; row < nodesPerSide - 1; row++) {
					beginShape(QUAD_STRIP)
					for (let col = 0; col < nodesPerSide; col++) {
						for (let off = 0; off < 2; off++) {
							const node1 = nodes1[(row + off) * nodesPerSide + col]
							const node2 = nodes2[(row + off) * nodesPerSide + col]
							var node = frame.id === 0 ? node1 : node2
							vertex(
								map(lerp(node1.x, node2.x, t), 0, 1, -sideLength/2, sideLength/2),
								map(lerp(node1.y, node2.y, t), 0, 1, -sideLength/2, sideLength/2),
								0,
								node.x,
								node.y
							)
						}
					}
					endShape()
				}
				pop()
			})
			push()
			blendMode(ADD)
			noStroke()
			texture(fbo.color)
			tint(255, alpha * 255)
			plane(width, -height)
			pop()
		}
		pop()
	}
}

function nodeProximity(mouse, node) {
	const nodeX = map(node.x, 0, 1, -sideLength/2, sideLength/2)
	const nodeY = map(node.y, 0, 1, -sideLength/2, sideLength/2)
	const dist = createVector(nodeX, nodeY).sub(mouse).mag() - nodeR
	return constrain(dist/r.value(), 0, 1)
}

